\set ON_ERROR_STOP on
set timezone='UTC';
create schema onboarding_test;
create function onboarding_test.id(n integer) returns uuid language sql immutable as $$select ('99920000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create table onboarding_test.ids(key text primary key,id uuid not null);
create table onboarding_test.evidence(name text primary key,value jsonb not null);
grant usage on schema onboarding_test to authenticated;
grant select,insert on all tables in schema onboarding_test to authenticated;
insert into auth.users(id,email) select onboarding_test.id(n),'onboarding-'||n||'@example.test' from generate_series(1,5) n;
select set_config('request.jwt.claim.sub',onboarding_test.id(1)::text,false);
insert into onboarding_test.ids select 'team',team_id from public.create_team_workspace('Actual onboarding team','ON-12345');
create function onboarding_test.team() returns uuid language sql stable as $$select id from onboarding_test.ids where key='team'$$;
select set_config('request.jwt.claim.sub',onboarding_test.id(2)::text,false);
set role authenticated;
do $$begin assert (select name='Actual onboarding team' from public.teams where code='ON-12345'),'Authenticated code preview failed';assert not exists(select 1 from public.team_members where team_id=onboarding_test.team()),'Preview exposed roster';end$$;
insert into onboarding_test.evidence select 'preview',jsonb_build_object('id',id,'name',name) from public.teams where code='ON-12345';
insert into public.join_requests(id,team_id,profile_id,requested_role,status,reviewed_by,reviewed_at) values(onboarding_test.id(10),onboarding_test.team(),auth.uid(),'worship_leader','pending',null,null);
insert into onboarding_test.evidence select 'pending',to_jsonb(r) from public.join_requests r where id=onboarding_test.id(10) and profile_id=auth.uid();
do $$declare blocked boolean:=false;begin begin update public.join_requests set requested_role='member' where id=onboarding_test.id(10);exception when insufficient_privilege then blocked:=true;end;assert blocked,'Join identity/role was mutable';end$$;
update public.join_requests set status='canceled',reviewed_by=null,reviewed_at=null where id=onboarding_test.id(10) and profile_id=auth.uid() and status='pending';
insert into onboarding_test.evidence select 'canceled',to_jsonb(r) from public.join_requests r where id=onboarding_test.id(10) and profile_id=auth.uid();
do $$declare n integer;begin update public.join_requests set status='canceled',reviewed_by=null,reviewed_at=null where id=onboarding_test.id(10) and profile_id=auth.uid() and status='pending';get diagnostics n=row_count;assert n=0,'Cancel retry mutated terminal row';end$$;
reset role;
select set_config('request.jwt.claim.sub',onboarding_test.id(3)::text,false);
set role authenticated;
do $$declare blocked boolean:=false;begin
 assert not exists(select 1 from public.join_requests where id=onboarding_test.id(10)),'Other account request exposed';
 begin insert into public.join_requests(id,team_id,profile_id,requested_role,status) values(onboarding_test.id(11),onboarding_test.team(),onboarding_test.id(2),'member','pending');exception when insufficient_privilege then blocked:=true;end;
 assert blocked,'Other account insertion allowed';
end$$;
do $$declare blocked boolean:=false;begin begin insert into public.join_requests(id,team_id,profile_id,requested_role,status) values(onboarding_test.id(12),onboarding_test.team(),auth.uid(),'owner','pending');exception when insufficient_privilege then blocked:=true;end;assert blocked,'Owner role request allowed';end$$;
insert into public.join_requests(id,team_id,profile_id,requested_role,status) values(onboarding_test.id(20),onboarding_test.team(),auth.uid(),'member','pending');
reset role;
select set_config('request.jwt.claim.sub',onboarding_test.id(4)::text,false);
set role authenticated;
insert into public.join_requests(id,team_id,profile_id,requested_role,status) values(onboarding_test.id(21),onboarding_test.team(),auth.uid(),'dancer','pending');
reset role;
select set_config('request.jwt.claim.sub',onboarding_test.id(1)::text,false);
set role authenticated;
select public.review_join_request(onboarding_test.id(21),'rejected');
reset role;
select set_config('request.jwt.claim.sub',onboarding_test.id(4)::text,false);
set role authenticated;
insert into onboarding_test.evidence select 'rejected',to_jsonb(r) from public.join_requests r where id=onboarding_test.id(21) and profile_id=auth.uid();
do $$declare blocked boolean:=false;begin begin insert into public.join_requests(id,team_id,profile_id,requested_role,status) values(onboarding_test.id(22),onboarding_test.team(),auth.uid(),'member','pending');exception when unique_violation then blocked:=true;end;assert blocked,'Terminal team/account pair unexpectedly replaced';end$$;
reset role;
